// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.Health)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/members", wrapper.CreateMember)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/v1/members/{member_no}", wrapper.DeleteMember)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/members/{member_no}", wrapper.GetMember)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/v1/members/{member_no}", wrapper.UpdateMember)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/products", wrapper.CreateProduct)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/products/{product_no}", wrapper.GetProduct)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/sales", wrapper.CreateSale)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/sales/{sale_no}", wrapper.GetSale)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/v1/purchases", wrapper.CreatePurchase)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/purchases/{purchase_no}", wrapper.GetPurchase)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/v1/purchases/{purchase_no}/histories", wrapper.ListPurchaseHistories)

	return m
}

