// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// CreateMember 회원 등록
	// (POST /api/v1/members)
	CreateMember(ctx context.Context, request CreateMemberRequestObject) (CreateMemberResponseObject, error)
	// DeleteMember 회원 삭제
	// (DELETE /api/v1/members/{member_no})
	DeleteMember(ctx context.Context, request DeleteMemberRequestObject) (DeleteMemberResponseObject, error)
	// GetMember 회원 조회
	// (GET /api/v1/members/{member_no})
	GetMember(ctx context.Context, request GetMemberRequestObject) (GetMemberResponseObject, error)
	// UpdateMember 회원 전체 수정
	// (PUT /api/v1/members/{member_no})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// CreateProduct 상품 등록
	// (POST /api/v1/products)
	CreateProduct(ctx context.Context, request CreateProductRequestObject) (CreateProductResponseObject, error)
	// GetProduct 상품 조회
	// (GET /api/v1/products/{product_no})
	GetProduct(ctx context.Context, request GetProductRequestObject) (GetProductResponseObject, error)
	// CreatePurchase 구매 생성
	// (POST /api/v1/purchases)
	CreatePurchase(ctx context.Context, request CreatePurchaseRequestObject) (CreatePurchaseResponseObject, error)
	// GetPurchase 구매 조회
	// (GET /api/v1/purchases/{purchase_no})
	GetPurchase(ctx context.Context, request GetPurchaseRequestObject) (GetPurchaseResponseObject, error)
	// ListPurchaseHistories 구매 이력 조회
	// (GET /api/v1/purchases/{purchase_no}/histories)
	ListPurchaseHistories(ctx context.Context, request ListPurchaseHistoriesRequestObject) (ListPurchaseHistoriesResponseObject, error)
	// CreateSale 판매 등록
	// (POST /api/v1/sales)
	CreateSale(ctx context.Context, request CreateSaleRequestObject) (CreateSaleResponseObject, error)
	// GetSale 판매 조회
	// (GET /api/v1/sales/{sale_no})
	GetSale(ctx context.Context, request GetSaleRequestObject) (GetSaleResponseObject, error)
	// Health 상태 확인
	// (GET /health)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
}

